import { readFileSync, writeFileSync, mkdirSync, mkdtempSync, copyFileSync, rmSync, renameSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { resolve, dirname } from 'node:path'
import { spawnSync } from 'node:child_process'
import { createVisualizationContextVerifier as createPrivate, hasVerifiedVisualizationContext } from '/home/enpasos/projects/skillpilot/qa-artifacts/ci-contract-audit/2026-11-07/economics-additional-existing-reviewed-context-candidate/goalVisualizationReviewedContext.private.ts'
import { createVisualizationContextVerifier as createActive } from '/home/enpasos/projects/skillpilot/app/scripts/goalVisualizationReviewedContext.ts'
const root='/home/enpasos/projects/skillpilot'
const candidate=root+'/qa-artifacts/ci-contract-audit/2026-11-07/economics-additional-existing-reviewed-context-candidate'
const out=root+'/qa-artifacts/ci-contract-audit/2026-11-07/economics-additional-existing-reviewed-context-independent-peer/input-edge-review.json'
const index=JSON.parse(readFileSync(candidate+'/candidate-index.json','utf8'))
const pin=JSON.parse(readFileSync(candidate+'/private-family-pins.json','utf8'))
const sha=(b:Buffer)=>createHash('sha256').update(b).digest('hex')
const json=(v:any)=>Buffer.from(JSON.stringify(v,null,2)+'\n')
const inputPaths=[...new Set([...index.activeInputPins.map((x:any)=>x.path),...index.candidateReceipts.map((x:any)=>x.path),'qa-artifacts/ci-contract-audit/2026-11-07/economics-additional-existing-reviewed-context-candidate/economicsQ2MonetarySocialContext.private.ts','qa-artifacts/ci-contract-audit/2026-11-07/economics-additional-existing-reviewed-context-candidate/goalVisualizationReviewedContext.private.ts','qa-artifacts/ci-contract-audit/2026-11-07/economics-additional-existing-reviewed-context-candidate/private-family-pins.json','app/scripts/lib/authenticatedGitEvidence.ts'])] as string[]
const before=inputPaths.map(path=>({path,sha256:sha(readFileSync(resolve(root,path)))}))
const scratch=mkdtempSync('/dev/shm/econ-own-input-edge-')
const current=resolve(scratch,'current'),originals=resolve(scratch,'originals')
mkdirSync(current);mkdirSync(originals)
const gitdir=spawnSync('git',['-C',root,'rev-parse','--absolute-git-dir'],{encoding:'utf8'});if(gitdir.status!==0)throw Error('gitdir')
writeFileSync(resolve(originals,'.git'),'gitdir: '+gitdir.stdout.trim()+'\n')
const copy=(base:string,path:string)=>{const dest=resolve(base,path);mkdirSync(dirname(dest),{recursive:true});copyFileSync(resolve(root,path),dest)}
const results:any[]=[];const seen=new Map<string,any>()
const privateVerifier=createPrivate({repositoryRoot:current,originalEvidenceRepositoryRoot:originals,acceptedRepositoryCommit:index.acceptedRepositoryCommit,onAuthenticatedOriginalRead(ref,required){seen.set(ref.gitCommit+':'+ref.path,{...ref,currentCopyRequired:required})}})
const activeVerifier=createActive({repositoryRoot:current,originalEvidenceRepositoryRoot:originals,acceptedRepositoryCommit:index.acceptedRepositoryCommit})
const emit=(v:any)=>{const raw=json(v);writeFileSync(resolve(current,'receipt.json'),raw);return{path:'receipt.json',sha256:sha(raw)}}
const check=(name:string,expected:string,ref:any,ctx:any,verify=privateVerifier)=>{const r=verify(ref,ctx);const actual=r.ok?'ok':r.status;results.push({name,expected,actual,issues:r.ok?[]:r.issues});if(actual!==expected)throw Error('Unexpected outcome: '+name+' '+actual);return r}
try{
 for(const [position,label] of [[0,'normal'],[index.rows.findIndex((x:any)=>x.corrected),'correction']] as [number,string][]){
  const row=index.rows[position],reference=index.candidateReceipts[position];for(const dep of row.originalDependencies)copy(originals,dep.path);for(const p of [row.current.publicAssetPath,row.current.canonicalAssetPath])copy(current,p)
  const receipt=JSON.parse(readFileSync(resolve(root,reference.path),'utf8'));const ctx=row.current
  const baseline=emit(receipt);const cap=check(label+': authentic complete inputs','ok',baseline,ctx)
  results.push({name:label+': plain copied capability cannot grant authority',expected:false,actual:cap.ok?hasVerifiedVisualizationContext({...cap.capability},ctx):null})
  check(label+': missing receipt','missing',undefined,ctx)
  check(label+': changed complete German description','stale',baseline,{...ctx,description:ctx.description+' neue Fachbehauptung'})
  check(label+': wrong owner in current scope','stale',baseline,{...ctx,landscapeId:'00000000-0000-0000-0000-000000000000'})
  check(label+': wrong subject in current scope','stale',baseline,{...ctx,subject:'mathematik'})
  check(label+': receipt nominates other owner','invalid',emit({...receipt,context:{...receipt.context,landscapeId:'00000000-0000-0000-0000-000000000000'}}),ctx)
  check(label+': source edge removed','invalid',emit({...receipt,ownerSource:undefined}),ctx)
  check(label+': author input edge replaced by source','invalid',emit({...receipt,originalInput:receipt.ownerSource}),ctx)
  check(label+': original review newer accepted commit','invalid',emit({...receipt,originalReview:{...receipt.originalReview,gitCommit:index.acceptedRepositoryCommit}}),ctx)
  check(label+': original review path traversal','invalid',emit({...receipt,originalReview:{...receipt.originalReview,path:'../'+receipt.originalReview.path}}),ctx)
  check(label+': reviewed asset edge removed','invalid',emit({...receipt,reviewedAsset:undefined}),ctx)
  check(label+': current primary URL missing','invalid',emit(receipt),{...ctx,imageUrl:''})
  check(label+': current canonical asset missing','invalid',emit(receipt),{...ctx,canonicalAssetPath:'missing.png'})
  for(const profile of ['matrix-candidate-v1','economics-native-v1','diagram-current-b-v1','economics-q3-embedded-v1','economics-q3-trade-finance-v1'])check(label+': unchanged '+profile+' does not accept new original','invalid',emit({...receipt,reviewProfile:profile}),ctx,activeVerifier)
  for(const dep of row.originalDependencies.filter((x:any)=>!x.path.includes('/canonical/'))){
   const p=resolve(originals,dep.path),bak=p+'.missing';renameSync(p,bak);check(label+': missing actual original dependency '+dep.path,'invalid',emit(receipt),ctx);renameSync(bak,p)
  }
  const target=resolve(originals,receipt.originalReview.path),original=readFileSync(target),forged=JSON.parse(original.toString());forged.reviewedAt='2026-11-07T04:21:07Z';forged.reviewDate='2026-11-07';forged.actualInspection.fachlichePruefung='KEEP. Source keywords match.';const forgedRaw=json(forged);writeFileSync(target,forgedRaw)
  check(label+': today forged local KEEP cannot replace historical original','invalid',emit(receipt),ctx)
  check(label+': rehashed today forged original cannot self-authorize','invalid',emit({...receipt,originalReview:{...receipt.originalReview,sha256:sha(forgedRaw)},originalInput:{...receipt.originalInput,sha256:sha(forgedRaw)},reviewedAt:forged.reviewedAt,originalReason:forged.actualInspection.fachlichePruefung}),ctx)
  writeFileSync(target,original)
  if(label==='normal'){
   check('normal: missing actual supplied English title','stale',emit(receipt),{...ctx,titleEn:undefined})
   check('normal: altered actual supplied demand','stale',emit(receipt),{...ctx,demandLevel:'AB1'})
   check('normal: omit receipt demand field','invalid',emit({...receipt,context:{...receipt.context,demandLevel:undefined}}),ctx)
  }else{
   check('correction: current unreviewed English may differ but is not certified','ok',emit(receipt),{...ctx,titleEn:'unreviewed changed English title',descriptionEn:'unreviewed changed English description',demandLevel:'AB1'})
   check('correction: receipt cannot invent English scope','invalid',emit({...receipt,context:{...receipt.context,titleEn:ctx.titleEn}}),ctx)
   check('correction: receipt cannot invent demand scope','invalid',emit({...receipt,context:{...receipt.context,demandLevel:ctx.demandLevel}}),ctx)
   const prior=row.originalDependencies.find((x:any)=>x.path.endsWith('/independent-image-review.receipt.json')&&!x.path.includes('/correction-v2/'))
   check('correction: preserved REJECT cannot stand in for corrected KEEP','invalid',emit({...receipt,originalReview:prior,originalInput:prior}),ctx)
  }
 }
 const after=before.map(x=>({...x,sha256After:sha(readFileSync(resolve(root,x.path)))}))
 const result={reviewKind:'independent-adversarial-input-edge-review',startedBeforeFirstInputReadUtc:'2026-11-07T04:21:07Z',completedUtc:new Date().toISOString(),requestedModel:'gpt-6-astra',requestedReasoningEffort:'ultra',runtimeModelIndependentlyVerified:false,seed:null,backendParameters:null,claim:'No tested original/input/scope forgery bypass observed within fixed current profile; integration obligations remain separate.',cases:results,caseCount:results.length,allExpectationsMet:results.every(x=>x.expected===x.actual),originalsRead:seen.size,originalPinsSeen:[...seen.values()],codeAndInputPins:after,protectedInputsUnchanged:after.every(x=>x.sha256===x.sha256After),limits:['Current canonical-source and primary-resourceLink resolution are the caller/driver responsibility. Generic verifier authenticates the supplied current context plus actual image bytes, not a caller-supplied canonical source file.','Correction676684da intentionally attests only German title/description and image. A successful correction capability does not cover English or demand fields.','The exact pinned original family is closed, not a generic acceptance rule for all similar-looking later reviews.','No new AI subject-matter image judgment or human approval, no authority/capsule integration or M6/M7 claim.','No active source, QA, Git/index or candidate bytes were written; temporary originals and cases existed only under /dev/shm.']}
 mkdirSync(dirname(out),{recursive:true});writeFileSync(out,JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({cases:results.length,allExpectationsMet:result.allExpectationsMet,originalsRead:seen.size,inputsUnchanged:result.protectedInputsUnchanged,output:out}))
}finally{rmSync(scratch,{recursive:true,force:true})}
